// SPDX-License-Identifier: GPL-3.0

pragma solidity >=0.4.22 <0.9.0;

library Assert {

  event AssertionEvent(
    bool passed,
    string message,
    string methodName
  );

  event AssertionEventUint(
    bool passed,
    string message,
    string methodName,
    uint256 returned,
    uint256 expected
  );

  event AssertionEventInt(
    bool passed,
    string message,
    string methodName,
    int256 returned,
    int256 expected
  );

  event AssertionEventBool(
    bool passed,
    string message,
    string methodName,
    bool returned,
    bool expected
  );

  event AssertionEventAddress(
    bool passed,
    string message,
    string methodName,
    address returned,
    address expected
  );

  event AssertionEventBytes32(
    bool passed,
    string message,
    string methodName,
    bytes32 returned,
    bytes32 expected
  );

  event AssertionEventString(
    bool passed,
    string message,
    string methodName,
    string returned,
    string expected
  );

  event AssertionEventUintInt(
    bool passed,
    string message,
    string methodName,
    uint256 returned,
    int256 expected
  );

  event AssertionEventIntUint(
    bool passed,
    string message,
    string methodName,
    int256 returned,
    uint256 expected
  );

  function ok(bool a, string memory message) public returns (bool result) {
    result = a;
    emit AssertionEvent(result, message, "ok");
  }

  function equal(uint256 a, uint256 b, string memory message) public returns (bool result) {
    result = (a == b);
    emit AssertionEventUint(result, message, "equal", a, b);
  }

  function equal(int256 a, int256 b, string memory message) public returns (bool result) {
    result = (a == b);
    emit AssertionEventInt(result, message, "equal", a, b);
  }

  function equal(bool a, bool b, string memory message) public returns (bool result) {
    result = (a == b);
    emit AssertionEventBool(result, message, "equal", a, b);
  }

  // TODO: only for certain versions of solc
  //function equal(fixed a, fixed b, string message) public returns (bool result) {
  //  result = (a == b);
  //  emit AssertionEvent(result, message);
  //}

  // TODO: only for certain versions of solc
  //function equal(ufixed a, ufixed b, string message) public returns (bool result) {
  //  result = (a == b);
  //  emit AssertionEvent(result, message);
  //}

  function equal(address a, address b, string memory message) public returns (bool result) {
    result = (a == b);
    emit AssertionEventAddress(result, message, "equal", a, b);
  }

  function equal(bytes32 a, bytes32 b, string memory message) public returns (bool result) {
    result = (a == b);
    emit AssertionEventBytes32(result, message, "equal", a, b);
  }

  function equal(string memory a, string memory b, string memory message) public returns (bool result) {
     result = (keccak256(abi.encodePacked(a)) == keccak256(abi.encodePacked(b)));
     emit AssertionEventString(result, message, "equal", a, b);
  }

  function notEqual(uint256 a, uint256 b, string memory message) public returns (bool result) {
    result = (a != b);
    emit AssertionEventUint(result, message, "notEqual", a, b);
  }

  function notEqual(int256 a, int256 b, string memory message) public returns (bool result) {
    result = (a != b);
    emit AssertionEventInt(result, message, "notEqual", a, b);
  }

  function notEqual(bool a, bool b, string memory message) public returns (bool result) {
    result = (a != b);
    emit AssertionEventBool(result, message, "notEqual", a, b);
  }

  // TODO: only for certain versions of solc
  //function notEqual(fixed a, fixed b, string message) public returns (bool result) {
  //  result = (a != b);
  //  emit AssertionEvent(result, message);
  //}

  // TODO: only for certain versions of solc
  //function notEqual(ufixed a, ufixed b, string message) public returns (bool result) {
  //  result = (a != b);
  //  emit AssertionEvent(result, message);
  //}

  function notEqual(address a, address b, string memory message) public returns (bool result) {
    result = (a != b);
    emit AssertionEventAddress(result, message, "notEqual", a, b);
  }

  function notEqual(bytes32 a, bytes32 b, string memory message) public returns (bool result) {
    result = (a != b);
    emit AssertionEventBytes32(result, message, "notEqual", a, b);
  }

  function notEqual(string memory a, string memory b, string memory message) public returns (bool result) {
    result = (keccak256(abi.encodePacked(a)) != keccak256(abi.encodePacked(b)));
    emit AssertionEventString(result, message, "notEqual", a, b);
  }

  /*----------------- Greater than --------------------*/
  function greaterThan(uint256 a, uint256 b, string memory message) public returns (bool result) {
    result = (a > b);
    emit AssertionEventUint(result, message, "greaterThan", a, b);
  }

  function greaterThan(int256 a, int256 b, string memory message) public returns (bool result) {
    result = (a > b);
    emit AssertionEventInt(result, message, "greaterThan", a, b);
  }
  // TODO: safely compare between uint and int
  function greaterThan(uint256 a, int256 b, string memory message) public returns (bool result) {
    if(b < int(0)) {
      // int is negative uint "a" always greater
      result = true;
    } else {
      result = (a > uint(b));
    }
    emit AssertionEventUintInt(result, message, "greaterThan", a, b);
  }
  function greaterThan(int256 a, uint256 b, string memory message) public returns (bool result) {
    if(a < int(0)) {
      // int is negative uint "b" always greater
      result = false;
    } else {
      result = (uint(a) > b);
    }
    emit AssertionEventIntUint(result, message, "greaterThan", a, b);
  }
  /*----------------- Lesser than --------------------*/
  function lesserThan(uint256 a, uint256 b, string memory message) public returns (bool result) {
    result = (a < b);
    emit AssertionEventUint(result, message, "lesserThan", a, b);
  }

  function lesserThan(int256 a, int256 b, string memory message) public returns (bool result) {
    result = (a < b);
    emit AssertionEventInt(result, message, "lesserThan", a, b);
  }
  // TODO: safely compare between uint and int
  function lesserThan(uint256 a, int256 b, string memory message) public returns (bool result) {
    if(b < int(0)) {
      // int is negative int "b" always lesser
      result = false;
    } else {
      result = (a < uint(b));
    }
    emit AssertionEventUintInt(result, message, "lesserThan", a, b);
  }

  function lesserThan(int256 a, uint256 b, string memory message) public returns (bool result) {
    if(a < int(0)) {
      // int is negative int "a" always lesser
      result = true;
    } else {
      result = (uint(a) < b);
    }
    emit AssertionEventIntUint(result, message, "lesserThan", a, b);
  }
}

contracts/moduloA/MultifirmaUBO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IMultifirmaUBO.sol";

/// @title MultifirmaUBO — PLANTILLA del Módulo A (Curso A)
/// @notice Multifirma m de n de las autoridades de la UBO.
/// @dev    Completar todos los bloques marcados con TODO. No usar bibliotecas externas.
///         Requisitos mínimos:
///         - Constructor: lista de firmantes sin duplicados ni address(0), 1 <= umbral <= n.
///         - Un firmante no puede confirmar dos veces la misma propuesta.
///         - Una propuesta solo se ejecuta una vez y solo con confirmaciones >= umbral.
///         - Si la llamada al destino falla, ejecutar() revierte.
contract MultifirmaUBO is IMultifirmaUBO {
    // ---------------------------------------------------------------
    // Errores personalizados (más baratos en gas que los mensajes de texto)
    // ---------------------------------------------------------------
    error NoEsFirmante(address cuenta);
    error ConfiguracionInvalida();
    error PropuestaInexistente(uint256 id);
    error YaConfirmada(uint256 id, address firmante);
    error NoConfirmada(uint256 id, address firmante);
    error YaEjecutada(uint256 id);
    error ConfirmacionesInsuficientes(uint256 id, uint256 tiene, uint256 necesita);
    error LlamadaFallida(uint256 id);
    error DestinoSinCodigo(address destino);

    struct Propuesta_ {
        address destino;
        bytes datos;
        uint256 confirmaciones;
        bool ejecutada;
    }

    address[] private _firmantes;
    mapping(address => bool) private _esFirmante;
    uint256 private _umbral;
    Propuesta_[] private _propuestas;
    mapping(uint256 => mapping(address => bool)) private _haConfirmado;

    modifier soloFirmante() {
        if (!_esFirmante[msg.sender]) revert NoEsFirmante(msg.sender);
        _;
    }

    modifier existe(uint256 id) {
        if (id >= _propuestas.length) revert PropuestaInexistente(id);
        _;
    }

    constructor(address[] memory firmantes_, uint256 umbral_) {
        // Validar umbral_ (1 <= umbral_ <= firmantes_.length)
        if (umbral_ < 1 || umbral_ > firmantes_.length) revert ConfiguracionInvalida();
        // Recorrer firmantes_, rechazar address(0) y duplicados, y registrarlos
        for (uint256 i = 0; i < firmantes_.length; i++) {
            address f = firmantes_[i];
            if (f == address(0) || _esFirmante[f]) revert ConfiguracionInvalida();
            _esFirmante[f] = true;
            _firmantes.push(f);
        }
        _umbral = umbral_;
    }

    function proponer(address destino, bytes calldata datos)
        external
        override
        soloFirmante
        returns (uint256 id)
    {
        // Guardar la propuesta
        id = _propuestas.length; // el id es el largo ANTES de añadir
        _propuestas.push(Propuesta_(destino, datos, 0, false));
        emit Propuesta(id, msg.sender, destino, datos);
    }

    function confirmar(uint256 id) external override soloFirmante existe(id) {
        // Comprobar que no está ejecutada ni confirmada por msg.sender
        Propuesta_ storage p = _propuestas[id]; // storage: el cambio debe persistir
        if (p.ejecutada) revert YaEjecutada(id);
        if (_haConfirmado[id][msg.sender]) revert YaConfirmada(id, msg.sender);
        // Registrar la confirmación
        _haConfirmado[id][msg.sender] = true;
        p.confirmaciones += 1;
        emit Confirmacion(id, msg.sender);
    }

    function revocarConfirmacion(uint256 id) external override soloFirmante existe(id) {
        Propuesta_ storage p = _propuestas[id];
        // Solo se puede retirar antes de ejecutar y si el firmante había confirmado
        if (p.ejecutada) revert YaEjecutada(id);
        if (!_haConfirmado[id][msg.sender]) revert NoConfirmada(id, msg.sender);
        _haConfirmado[id][msg.sender] = false;
        p.confirmaciones -= 1;
        emit ConfirmacionRevocada(id, msg.sender);
    }

    function ejecutar(uint256 id) external override soloFirmante existe(id) {
        Propuesta_ storage p = _propuestas[id];

        // Comprobar umbral y que no esté ejecutada
        if (p.ejecutada) revert YaEjecutada(id);
        if (p.confirmaciones < _umbral) {
            revert ConfirmacionesInsuficientes(id, p.confirmaciones, _umbral);
        }

        // Una llamada a una dirección sin contrato devuelve éxito sin hacer nada:
        // se rechaza antes de marcar la propuesta.
        if (p.destino.code.length == 0) revert DestinoSinCodigo(p.destino);

        // Marcar como ejecutada ANTES de la llamada externa (patrón CEI).
        // Sirve contra la REENTRADA: si el destino vuelve a llamar a ejecutar(id)
        // durante la llamada, ya la encuentra marcada y revierte.
        p.ejecutada = true;

        // Llamar a destino con datos; si falla, revertir con LlamadaFallida.
        // OJO: al revertir se deshace TODO, también la marca. La propuesta queda
        // pendiente y puede reintentarse; no bloquea a las demás propuestas.
        // (Diseño alternativo, para discutir: no revertir y registrar el fallo.)
        (bool ok, ) = p.destino.call(p.datos);
        if (!ok) revert LlamadaFallida(id);

        emit Ejecucion(id);
    }

    function esFirmante(address cuenta) external view override returns (bool) {
        return _esFirmante[cuenta];
    }

    function umbral() external view override returns (uint256) {
        return _umbral;
    }

    function numeroConfirmaciones(uint256 id) external view override existe(id) returns (uint256) {
        return _propuestas[id].confirmaciones;
    }

    /// @notice Lista de firmantes (útil para las pruebas).
    function firmantes() external view returns (address[] memory) {
        return _firmantes;
    }

    // ---------------------------------------------------------------
    // OPCIONAL CON BONIFICACIÓN: rotación de firmantes.
    // Pista: estas funciones solo deben poder llamarse desde la propia
    // multifirma (msg.sender == address(this)), es decir, mediante una propuesta.
    // function reemplazarFirmante(address antiguo, address nuevo) external { ... }
    // ---------------------------------------------------------------
}

contracts/interfaces/IMultifirmaUBO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IMultifirmaUBO — Interfaz del Módulo A (Curso A)
/// @notice Multifirma m de n de las autoridades de la UBO. Es la única cuenta
///         con permiso para autorizar y revocar emisores en RegistroEmisores.
/// @dev    NO MODIFICAR sin acuerdo de los tres cursos.
interface IMultifirmaUBO {
    event Propuesta(uint256 indexed id, address indexed proponente, address destino, bytes datos);
    event Confirmacion(uint256 indexed id, address indexed firmante);
    event ConfirmacionRevocada(uint256 indexed id, address indexed firmante);
    event Ejecucion(uint256 indexed id);

    /// @notice Propone una llamada a `destino` con `datos` (calldata codificado).
    ///         Solo firmantes. La propuesta NO cuenta como confirmación automática.
    /// @return id Identificador de la propuesta (empieza en 0).
    function proponer(address destino, bytes calldata datos) external returns (uint256 id);

    /// @notice Confirma una propuesta. Solo firmantes; una vez por firmante.
    function confirmar(uint256 id) external;

    /// @notice Retira la propia confirmación antes de que se ejecute.
    function revocarConfirmacion(uint256 id) external;

    /// @notice Ejecuta la propuesta si tiene al menos `umbral()` confirmaciones.
    ///         Solo firmantes; una única vez. Revierte si la llamada falla.
    function ejecutar(uint256 id) external;

    function esFirmante(address cuenta) external view returns (bool);
    function umbral() external view returns (uint256);
    function numeroConfirmaciones(uint256 id) external view returns (uint256);
}

contracts/moduloA/RegistroEmisores.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IRegistroEmisores.sol";
import "../comun/ConstantesUBO.sol";

/// @title RegistroEmisores — PLANTILLA del Módulo A (Curso A)
/// @notice Emisores autorizados por facultad, con historial completo.
/// @dev    Completar los TODO. Requisitos mínimos:
///         - Solo `administracion` (la dirección de MultifirmaUBO) autoriza y revoca.
///         - Solo facultades válidas (ConstantesUBO.esFacultadValida).
///         - Historial de TODOS los periodos: un emisor puede ser autorizado,
///           revocado y vuelto a autorizar; estabaAutorizado() debe acertar
///           para cualquier momento pasado.
///         - Periodos semiabiertos [desde, hasta); hasta = 0 significa abierto.
contract RegistroEmisores is IRegistroEmisores {
    error NoEsAdministracion(address cuenta);
    error FacultadInvalida(bytes32 facultad);
    error DireccionInvalida();
    error YaAutorizado(address emisor, bytes32 facultad);
    error NoAutorizado(address emisor, bytes32 facultad);

    struct Periodo {
        uint64 desde;
        uint64 hasta; // 0 = abierto
    }

    /// @notice Dirección de la multifirma de la UBO.
    address public immutable administracion;

    /// @dev Historial de periodos por emisor y facultad, en orden cronológico.
    mapping(address => mapping(bytes32 => Periodo[])) private _periodos;

    modifier soloAdministracion() {
        if (msg.sender != administracion) revert NoEsAdministracion(msg.sender);
        _;
    }

    constructor(address administracion_) {
        if (administracion_ == address(0)) revert DireccionInvalida();
        administracion = administracion_;
    }

    function autorizarEmisor(address emisor, bytes32 facultad) external override soloAdministracion {
        // Validar emisor != address(0) y facultad válida
        if (emisor == address(0)) revert DireccionInvalida();
        if (!ConstantesUBO.esFacultadValida(facultad)) revert FacultadInvalida(facultad);

        // Revertir con YaAutorizado si hay un periodo abierto
        Periodo[] storage ps = _periodos[emisor][facultad];
        if (ps.length > 0 && ps[ps.length - 1].hasta == 0) {
            revert YaAutorizado(emisor, facultad);
        }

        // Añadir Periodo(desde = block.timestamp, hasta = 0)
        uint64 ahora = uint64(block.timestamp);
        ps.push(Periodo(ahora, 0));
        emit EmisorAutorizado(emisor, facultad, ahora);
    }

    function revocarEmisor(address emisor, bytes32 facultad) external override soloAdministracion {
        // Revertir con NoAutorizado si no hay periodo abierto
        Periodo[] storage ps = _periodos[emisor][facultad];
        if (ps.length == 0 || ps[ps.length - 1].hasta != 0) {
            revert NoAutorizado(emisor, facultad);
        }
        // Cerrar el último periodo (hasta = block.timestamp)
        uint64 ahora = uint64(block.timestamp);
        ps[ps.length - 1].hasta = ahora;
        emit EmisorRevocado(emisor, facultad, ahora);
    }

    function estaAutorizado(address emisor, bytes32 facultad) public view override returns (bool) {
        // ¿El último periodo existe y está abierto?
        Periodo[] storage ps = _periodos[emisor][facultad];
        return ps.length > 0 && ps[ps.length - 1].hasta == 0;
    }

    function estabaAutorizado(address emisor, bytes32 facultad, uint256 momento)
        external
        view
        override
        returns (bool)
    {
        Periodo[] storage ps = _periodos[emisor][facultad];

        // Búsqueda binaria: primer periodo con desde > momento
        uint256 lo = 0;
        uint256 hi = ps.length;
        while (lo < hi) {
            uint256 mid = (lo + hi) / 2;
            if (ps[mid].desde <= momento) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }

        // Ningún periodo había empezado todavía
        if (lo == 0) return false;

        // El candidato es el último periodo con desde <= momento
        Periodo storage p = ps[lo - 1];
        return p.hasta == 0 || momento < p.hasta;
    }

    /// @notice Historial completo (útil para pruebas y auditoría).
    function periodos(address emisor, bytes32 facultad) external view returns (Periodo[] memory) {
        return _periodos[emisor][facultad];
    }
}

contracts/interfaces/IRegistroEmisores.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IRegistroEmisores — Interfaz del Módulo A (Curso A)
/// @notice Registro de las direcciones autorizadas para emitir títulos en
///         nombre de la UBO, por facultad, con memoria histórica.
/// @dev    NO MODIFICAR sin acuerdo de los tres cursos.
interface IRegistroEmisores {
    /// @notice Se emite cuando la administración autoriza a un emisor en una facultad.
    event EmisorAutorizado(address indexed emisor, bytes32 indexed facultad, uint256 desde);

    /// @notice Se emite cuando la administración retira la autorización.
    event EmisorRevocado(address indexed emisor, bytes32 indexed facultad, uint256 hasta);

    /// @notice Autoriza a `emisor` en `facultad`. Solo la administración (multifirma).
    /// @dev Debe revertir si el emisor ya está autorizado en esa facultad.
    function autorizarEmisor(address emisor, bytes32 facultad) external;

    /// @notice Retira la autorización de `emisor` en `facultad`. Solo la administración.
    /// @dev Debe revertir si el emisor no está autorizado en esa facultad.
    function revocarEmisor(address emisor, bytes32 facultad) external;

    /// @notice ¿Está autorizado AHORA `emisor` en `facultad`?
    function estaAutorizado(address emisor, bytes32 facultad) external view returns (bool);

    /// @notice ¿Estaba autorizado `emisor` en `facultad` en el instante `momento`
    ///         (marca de tiempo Unix, en segundos)?
    /// @dev Un periodo de autorización es el intervalo [desde, hasta):
    ///      incluye `desde` y excluye `hasta`. Un periodo abierto tiene hasta = 0.
    function estabaAutorizado(address emisor, bytes32 facultad, uint256 momento)
        external
        view
        returns (bool);
}

contracts/comun/ConstantesUBO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ConstantesUBO — Valores comunes a los tres módulos de Sello Libertador
/// @notice Uso: import "../comun/ConstantesUBO.sol";  y luego ConstantesUBO.ING
library ConstantesUBO {
    // ---------------------------------------------------------------
    // Facultades de la Universidad Bernardo O'Higgins
    // ---------------------------------------------------------------
    bytes32 internal constant ING = keccak256("ING"); // Ingeniería, Ciencia y Tecnología
    bytes32 internal constant HUM = keccak256("HUM"); // Ciencias Humanas
    bytes32 internal constant SAL = keccak256("SAL"); // Ciencias de la Salud
    bytes32 internal constant MED = keccak256("MED"); // Ciencias Médicas

    // ---------------------------------------------------------------
    // Códigos de motivo de suspensión o revocación (campo Titulo.motivo)
    // ---------------------------------------------------------------
    uint8 internal constant MOTIVO_NINGUNO = 0;
    uint8 internal constant MOTIVO_ERROR_ADMINISTRATIVO = 1;
    uint8 internal constant MOTIVO_FRAUDE = 2;
    uint8 internal constant MOTIVO_RESOLUCION_JUDICIAL = 3;
    uint8 internal constant MOTIVO_RECTIFICACION = 4;
    uint8 internal constant MOTIVO_EN_INVESTIGACION = 5; // típico de una suspensión

    // ---------------------------------------------------------------
    // Límites
    // ---------------------------------------------------------------
    /// @notice Máximo de títulos por llamada a emitirLote (evita DoS por límite de gas).
    uint256 internal constant MAX_LOTE = 50;

    /// @notice ¿Es una facultad reconocida?
    function esFacultadValida(bytes32 facultad) internal pure returns (bool) {
        return facultad == ING || facultad == HUM || facultad == SAL || facultad == MED;
    }

    /// @notice Compromiso criptográfico común a todo el sistema.
    /// @param sal           32 bytes aleatorios, incluidos en el documento cifrado del enlace.
    /// @param hashDocumento keccak256 del documento de la credencial en JSON
    ///                      canonicalizado (RFC 8785).
    function compromiso(bytes32 sal, bytes32 hashDocumento) internal pure returns (bytes32) {
        return keccak256(abi.encode(sal, hashDocumento));
    }

    /// @notice Hoja del árbol de Merkle de una ceremonia (ver IAnclajeLotes).
    function hojaLote(bytes10 localizador, bytes32 compromiso_) internal pure returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(localizador, compromiso_))));
    }
}

contracts/comun/ActorPruebas.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ActorPruebas — Auxiliar para las pruebas unitarias de Remix
/// @notice En las pruebas de Remix, el contrato de prueba siempre llama con su
///         propia dirección. Para simular a varias personas (tres firmantes, dos
///         emisores, un titulado), se despliega un ActorPruebas por persona y se
///         llama «a través» de él.
/// @dev    Ejemplo:
///             ActorPruebas rector = new ActorPruebas();
///             rector.llamar(address(multifirma),
///                 abi.encodeCall(IMultifirmaUBO.confirmar, (0)));
///         Si la llamada interna revierte, llamar() revierte con el mismo error,
///         por lo que puede usarse dentro de try/catch.
contract ActorPruebas {
    function llamar(address destino, bytes calldata datos) external returns (bytes memory resultado) {
        (bool ok, bytes memory ret) = destino.call(datos);
        if (!ok) {
            assembly {
                revert(add(ret, 32), mload(ret))
            }
        }
        return ret;
    }

    /// @notice Versión que no revierte: devuelve si la llamada tuvo éxito.
    function intentar(address destino, bytes calldata datos) external returns (bool ok) {
        (ok,) = destino.call(datos);
    }
}

